// TH14 v1.00b Stage 5 Boss spell 2 (spell id 72), st05bs.ecl.txt::BossCard2 625-674.
// Source entry is BossCard2; BossCard2_at / BossCard2_at_l / Ecl_EtBreak are closure.
// Native reset T0 == card frame 120 (opening buffer); native timeout 2100 -> Boss3 boundary.
// Spell names are difficulty split (!EN 天地有用 / !HL 天下転覆); UI text omitted.

const TIME_LIMIT: int = 2724;      // 120 opening + 2100 native + 500 tail + 4 startup
const OPENING_BUFFER: int = 120;
const TH14_FIREBALL_BLUE: int = 784;  // native etSprite type 26 color 3

// Slot 3 of the shared EX config: ANGLE_ACCEL type 8, a=50, r=0, s=(pi/300)*RANDF2.
// Slot 2 is WAIT 0x80000000 a=120, so the turn starts 120 frames after birth and
// lasts 50 frames. The per-wave random is bound once and shared by that wave's bullets.
// Birth ANIM (type 2, a=1) keeps its -4*velocity retreat; the animation/deceleration
// and no-hit window are omitted per the approved policy.
xformdef TH14_BOSS2_CURVE(omega: angle) {
    @120 add_speed(0fx);
    @50 set_ang_vel(omega);
    set_ang_vel(0deg);
}

sub th14_fire_at_bullet(ox: fx, oy: fx, speed: fx, a: angle, omega: angle) {
    var bx: fx = ox - 4fx * speed * cos(a);
    var by: fx = oy - 4fx * speed * sin(a);
    _ = fire(TH14_FIREBALL_BLUE, 3, bx, by, speed, a, TH14_BOSS2_CURVE(omega), none);
}

// BossCard2_at_588 / _1452: aimed three-way fan from the top edge.
// Draw order per wave: ANGLE_ACCEL s, etAngle base, etOffsetAbs x, etOffsetAbs y, etSpeed.
sub th14_at_wave(ax: fx, spread: fx) {
    var r1: int = rand(65536) - 32768;
    var omega: angle = ((r1 * 109) / 32768) as angle;       // pi/300 rad/frame -> BAM/frame
    var r2: int = rand(65536) - 32768;
    var base_off: angle = ((r2 * 1820) / 32768) as angle;   // 0.17453292 rad = 10 deg
    var r3: int = rand(65536) - 32768;
    var ox: fx = ax + ((r3 as fx) / 32768) * 16fx;
    var r4: int = rand(65536) - 32768;
    var oy: fx = ((r4 as fx) / 65536 + 0.5fx) * 64fx;
    var r5: int = rand(65536) - 32768;
    var speed: fx = 1.4fx + ((r5 as fx) / 65536 + 0.5fx) * spread;
    // etAim(0,0) = aimed fan; aim is taken from the absolute spawn point.
    var base: angle = atan2($player_y - oy, $player_x - ox) + base_off;
    th14_fire_at_bullet(ox, oy, speed, base, omega);            // F(3,0) = 0
    th14_fire_at_bullet(ox, oy, speed, base - 30deg, omega);    // F(3,1) = -delta
    th14_fire_at_bullet(ox, oy, speed, base + 30deg, omega);    // F(3,2) = +delta
}

// BossCard2_at_l_668 / _1420: fixed upward fan from y=448; Hard 1 way, Lunatic 2 ways.
// Draw order per wave: ANGLE_ACCEL s, etOffsetAbs x, etSpeed (etAngle is constant).
sub th14_at_l_wave(ax: fx, spread: fx, ways: int) {
    var r1: int = rand(65536) - 32768;
    var omega: angle = ((r1 * 109) / 32768) as angle;
    var r2: int = rand(65536) - 32768;
    var ox: fx = ax + ((r2 as fx) / 32768) * 16fx;
    var r3: int = rand(65536) - 32768;
    var speed: fx = 1.4fx + ((r3 as fx) / 65536 + 0.5fx) * spread;
    if ways == 1 {
        th14_fire_at_bullet(ox, 448fx, speed, 270deg, omega);
    } else {
        th14_fire_at_bullet(ox, 448fx, speed, 270deg + 10deg, omega);  // F(2,0) = +delta/2
        th14_fire_at_bullet(ox, 448fx, speed, 270deg - 10deg, omega);  // F(2,1) = -delta/2
    }
}

async sub card_at() {
    var rank: int = global(GVAR_RANK);
    var gap: int = 10;
    if rank == RANK_EASY { gap = 14; }
    if rank == RANK_NORMAL { gap = 7; }
    var waves: int = 1890 / gap;
    var j: int = 0;
    while j < waves {
        var idx: int = j % 26;
        var ax: fx = -192fx;
        if idx < 13 {
            ax = (-192 + 32 * idx) as fx;
        } else {
            ax = (192 - 32 * (idx - 13)) as fx;
        }
        var cyc: int = j / 26;
        if cyc > 10 { cyc = 10; }
        var spread: fx = (cyc as fx) * 0.1fx;
        th14_at_wave(ax, spread);
        j = j + 1;
        wait(gap);
    }
}

async sub card_at_l() {
    // at_l is spawned only on Hard/Lunatic, where the source wait is 10.
    var ways: int = 1;
    if global(GVAR_RANK) >= RANK_LUNATIC { ways = 2; }
    var waves: int = 189;
    var j: int = 0;
    while j < waves {
        var idx: int = j % 26;
        var ax: fx = -192fx;
        if idx < 13 {
            ax = (-192 + 32 * idx) as fx;
        } else {
            ax = (192 - 32 * (idx - 13)) as fx;
        }
        var cyc: int = j / 26;
        if cyc > 10 { cyc = 10; }
        var spread: fx = (cyc as fx) * 0.1fx;
        th14_at_l_wave(ax, spread, ways);
        j = j + 1;
        wait(10);
    }
}

// Ecl_EtBreak (default.ecl.txt:94-110): cancel a growing circle, A=16 then +10 per frame.
// Implemented as an owner task instead of a helper enemy; the field clear is identical.
async sub et_break_clear() {
    var a: fx = 16fx;
    while a < 640fx {
        clear_bullets_at(0fx, 0fx, a, 0);
        wait(1);
        a = a + 10fx;
    }
}

// --- moveRand(60, 0, 0.6) recipe with the source limits (0,128,280,256) ---
// Limit is x in [-140,140], y in [0,256]; the direction inner region is x+-70, y 64..192.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx * 0.01fx; }  // 0.6*(1-k/60)
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_dir(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else {
        if $self_x > 70fx {
            a = r / 3 + 32768;
            if a > 32768 { a = a - 65536; }
        } else {
            a = r / 4;
            var choose: int = rand(65536) % 3;
            if $player_x > $self_x {
                if choose == 0 { a = a + 32768; }
            } else {
                if choose != 0 { a = a + 32768; }
            }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else {
        if $self_y > 192fx {
            if a < 0 { a = -a; }
            a = -a;
        }
    }
    // Native guard around +-pi/2, epsilon 0.05 rad (~522 BAM).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_dir(a as angle);
}

// BossCard2 source timeline from its own timerReset.
async sub boss_card2() {
    wait(OPENING_BUFFER);
    spawn et_break_clear();
    // t0: moveVel/moveVelTime/movePosTime(0,...) resets are implicit on the fresh anchor
    // (0,128) from the public Boss entry. movePosTime(60,4,0,144) = quad-out move.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(150);   // t150; funcCall(2)+I0=3 (screen ANM) and unknown567(1) recorded, not emulated
    wait(60);    // t210
    spawn card_at();
    if global(GVAR_RANK) >= RANK_HARD { spawn card_at_l(); }
    wait(180);   // t390: first moveRand
    var st: int = 390;
    while st < 2100 {
        card_move_rand();
        var n: int = 0;
        while n < 120 && st < 2100 {
            wait(1);
            st = st + 1;
            n = n + 1;
            if st < 2100 { card_arm_next_step(); }
        }
    }
    // Source timeout -> Boss3 entry cleanup, but Boss3 itself is not part of this card.
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);    // source setHitbox(48,48), normal circular path -> radius 24
    set_hurtbox(24fx);   // source setHurtbox(48,48)
    spell_begin(0, 72, boss_card2, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 2100, 0, 0, 0, boss_main);
    loop { wait(1); }
}
